val BG=Color(0xFF07131F);val TOP=Color(0xFF171B29);val CARD=Color(0xFF102132);val BLUE=Color(0xFF3585EA);val MUT=Color(0xFF9BA9BC);val WHITE=Color(0xFFF8FAFD);val RED=Color(0xFFFF718B);val GREEN=Color(0xFF37D29F)
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{MaterialTheme(colorScheme=darkColorScheme(primary=BLUE,background=BG,surface=CARD,onSurface=WHITE,onBackground=WHITE)){App(this)}}}}
data class R(val code:Int,val body:String){val ok get()=code in 200..299}
class Api(val base:String,val token:String){suspend fun req(m:String,p:String,j:JSONObject?=null)=withContext(Dispatchers.IO){val c=URL(base.trimEnd('/')+"/api"+p).openConnection() as HttpURLConnection;c.requestMethod=m;c.connectTimeout=12000;c.readTimeout=30000;c.setRequestProperty("Authorization","Bearer $token");c.setRequestProperty("Accept","application/json,text/plain,*/*");j?.let{c.doOutput=true;c.setRequestProperty("Content-Type","application/json");c.outputStream.use{o->o.write(it.toString().toByteArray())}};val k=c.responseCode;val s=if(k in 200..299)c.inputStream else c.errorStream;R(k,s?.bufferedReader()?.use{it.readText()}.orEmpty())};suspend fun g(p:String)=req("GET",p);suspend fun p(p:String,j:JSONObject=JSONObject())=req("POST",p,j);suspend fun u(p:String,j:JSONObject)=req("PUT",p,j);suspend fun d(p:String,j:JSONObject?=null)=req("DELETE",p,j)}
@Composable fun App(ctx:Context){val sp=remember{ctx.getSharedPreferences("nodexa",0)};var b by remember{mutableStateOf(sp.getString("base","")?:"")};var t by remember{mutableStateOf(sp.getString("token","")?:"")};var server by remember{mutableStateOf<JSONObject?>(null)};Surface(Modifier.fillMaxSize(),color=BG){if(b.isBlank()||t.isBlank())Connect(b,t){x,y->b=x.trimEnd('/');t=y;sp.edit().putString("base",b).putString("token",t).apply()}else if(server==null)Servers(Api(b,t),{server=it}){sp.edit().clear().apply();b="";t=""}else Server(ctx,Api(b,t),server!!){server=null}}}
@Composable fun Field(v:String,on:(String)->Unit,label:String,ph:String="",pass:Boolean=false){OutlinedTextField(v,on,label={Text(label)},placeholder={Text(ph,color=MUT)},singleLine=true,textStyle=LocalTextStyle.current.copy(color=WHITE),visualTransformation=if(pass)PasswordVisualTransformation() else androidx.compose.ui.text.input.VisualTransformation.None,colors=OutlinedTextFieldDefaults.colors(focusedTextColor=WHITE,unfocusedTextColor=WHITE,focusedBorderColor=BLUE,unfocusedBorderColor=MUT,cursorColor=BLUE),modifier=Modifier.fillMaxWidth())}
@Composable fun Connect(b0:String,t0:String,go:(String,String)->Unit){var b by remember{mutableStateOf(b0)};var t by remember{mutableStateOf(t0)};Column(Modifier.fillMaxSize().padding(28.dp),verticalArrangement=Arrangement.Center){Box(Modifier.size(82.dp).background(BLUE,RoundedCornerShape(22.dp)),contentAlignment=Alignment.Center){Text("N",fontSize=42.sp,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(18.dp));Text("Nodexa",fontSize=40.sp,fontWeight=FontWeight.Bold);Text("GAME SERVER CLOUD",color=BLUE);Spacer(Modifier.height(35.dp));Text("Forbind til dit panel",fontSize=24.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(14.dp));Field(b,{b=it},"Panel URL","https://panel.example.com");Spacer(Modifier.height(10.dp));Field(t,{t=it},"Client API key","nxa_...",true);Spacer(Modifier.height(16.dp));Button({if(b.isNotBlank()&&t.isNotBlank())go(b,t)},Modifier.fillMaxWidth()){Text("Forbind")};Text("API-nøglen gemmes kun lokalt på enheden.",color=MUT,modifier=Modifier.padding(top=10.dp))}}
@Composable fun Bar(title:String,back:(()->Unit)?=null,acts:@Composable RowScope.()->Unit={}){Row(Modifier.fillMaxWidth().background(TOP).statusBarsPadding().height(70.dp).padding(horizontal=10.dp),verticalAlignment=Alignment.CenterVertically){back?.let{IconButton(it){Icon(Icons.Default.ArrowBack,null)}};Text(title,fontSize=25.sp,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f));acts()}}
fun objs(s:String):List<JSONObject>=runCatching{val x=s.trim();val a=if(x.startsWith("["))JSONArray(x)else JSONObject(x).optJSONArray("data")?:JSONArray();(0 until a.length()).mapNotNull{a.optJSONObject(it)}}.getOrDefault(emptyList())
fun msg(s:String)=runCatching{JSONObject(s).optString("message",s.take(200))}.getOrDefault(s.take(200));fun en(s:String)=URLEncoder.encode(s,"UTF-8");fun path(a:String,b:String)=if(a=="/")"/$b" else a.trimEnd('/')+"/$b"
@Composable fun Servers(api:Api,open:(JSONObject)->Unit,logout:()->Unit){var list by remember{mutableStateOf<List<JSONObject>>(emptyList())};var err by remember{mutableStateOf("")};val sc=rememberCoroutineScope();fun load(){sc.launch{val r=api.g("/servers");if(r.ok){list=objs(r.body);err=""}else err="HTTP ${r.code}: ${msg(r.body)}"}};LaunchedEffect(Unit){load()};Column{Bar("Nodexa",acts={IconButton({load()}){Icon(Icons.Default.Refresh,null)};IconButton(logout){Icon(Icons.Default.Logout,null)}});Text("Dine servere",fontSize=26.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(18.dp));if(err.isNotBlank())Text(err,color=RED,modifier=Modifier.padding(12.dp));LazyColumn(contentPadding=PaddingValues(14.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){items(list){s->Card(Modifier.fillMaxWidth().clickable{open(s)},colors=CardDefaults.cardColors(containerColor=Color(0xFF172E46))){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Dns,null,tint=BLUE);Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(s.optString("name","Server"),fontSize=20.sp,fontWeight=FontWeight.Bold);Text(s.optString("identifier"),color=MUT)};Icon(Icons.Default.ChevronRight,null)}}}}}}
@Composable fun Server(ctx:Context,api:Api,s:JSONObject,back:()->Unit){val id=s.optInt("id");var tab by remember{mutableIntStateOf(0)};val ts=listOf("Overview","Console","Files","Backups","Databases","Schedules","Users","Settings");Column{Bar(s.optString("name","Nodexa"),back);ScrollableTabRow(tab,containerColor=BG,edgePadding=4.dp){ts.forEachIndexed{i,n->Tab(tab==i,{tab=i},text={Text(n)})}};when(tab){0->Overview(api,id);1->Console(api,id);2->Files(api,id);3->Backups(api,id);4->Databases(ctx,api,id);5->Schedules(api,id);6->Users(api,id);else->Settings(api,id,s)}}}
@Composable fun BoxCard(title:String,body:@Composable ColumnScope.()->Unit){Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=CARD)){Column(Modifier.padding(18.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text(title,fontSize=21.sp,fontWeight=FontWeight.Bold);body()}}}
